import{_ as p,c as e,o as t,ah as s}from"./chunks/framework.Dnh4IO1K.js";const d=JSON.parse('{"title":"爻征第十六","description":"杭氏易学 - 爻征第十六","frontmatter":{"title":"爻征第十六","description":"杭氏易学 - 爻征第十六"},"headers":[],"relativePath":"zh/classics/hangshi/017.md","filePath":"zh/classics/hangshi/017.md"}'),r={name:"zh/classics/hangshi/017.md"};function i(n,a,c,_,o,h){return t(),e("div",null,[...a[0]||(a[0]=[s('<h1 id="爻征第十六" tabindex="-1">爻征第十六 <a class="header-anchor" href="#爻征第十六" aria-label="Permalink to “爻征第十六”">​</a></h1><p>征者，用之见乎外者也。寿阳阎氏《爻征广义》，详于郑氏爻辰，殊于实用无征焉。六爻制用，肆应不穷，皆以五行阳干阴支为纲领，以生克刑害少壮盛休废类别去取，以征吉凶。以其与卦爻象数，相为统系，足以推六十四卦变化往来之迹。且有与经传互相发明者，亦初学所不可不知者也。爰取《京氏易》与《易纬》诸书之著录者，分隶六爻，征爻用，亦以存古义也。至推演条理，今密于古，术家所习用，更毋庸备述焉。</p><p>六亲</p><p>京氏曰：“八卦鬼为系爻，财为制爻，天地为义爻，福德为宝爻，同气为专爻。”此五者，今术家谓之六亲 【亲者，族也。《易》曰“类族辨物”，先辨诸爻。】 ，盖与本身为六也。相传甚古，义简而赅，言占者所不能废。朱子《周易本义》，以周孔之《易》为教人卜筮之用，而焦京之言卜筮者，反悉废之，仅以六爻之动静为占，宜其无征验之可言也。兹以京说为主，而以近世皆用者附之。非敢谓援古证今，亦发其凡而已。</p><p>五者与本身为六。今称六亲者，义亦近古。亲者族也。类族辨物，举一起例，凡言兄弟，则比肩者可类；言子孙，则后我者可类；言父母，则庇我者皆其类；言妻财，则奉我者皆其类；言官鬼，则制我害我者皆其类。远近不同，则亲疏自异。而为利为害，爰有重轻之别。是在察其爻之所在，而鉴别之，非可概论也。</p><p>六神</p><p>神 【神者存也。成性存存，阴阳不测，假定其名，亦犹类族辨物之意也。】 也者，妙万物而为言。过化存神，有非可以迹象求之者。六亲征其实，六神征诸虚。周流六虚，无乎不在。渺焉漠焉，将何从征？曰阴阳之气，布为五行，其几甚微。《传》曰：“本于阴阳而立卦，阴阳变化，而神寓也。”此六爻之神所由名，要非泥其名以为实者也。</p><p>《传》曰：“前朱雀而后玄武，左青龙而右白虎。”古者五行各有专官，官世其守，功德在民，民不能忘。即假人名以神号，举其名知其用，所以便事也。吉凶神煞之名，皆此类也。必求其人以实之，愚也。必妄其名而斥之，亦讵足为智哉！六壬、太乙、遁甲之言神，举可隅反矣。</p><p>六属</p><p>六属者以五音分属六爻，即本于纳音。纳音与纳甲相表里。属之于爻，仍随八卦之纳甲以定其数也。举例如下：</p><p>不言乾坤，六子之爻，皆乾坤之爻也。《说卦》“神也者”一章，不言乾坤，非特六子之用，皆乾坤之用。而所谓神者，即乾坤之阴阳不测，周流六虚者也。纳音之说似浅而实深。精微之理，非可以迹象求之。谓之音者，乾坤爻辰左行右行。间辰六位，即六律六吕，相生之所本，故以分属六爻，各纳其辰，而谓之纳音。今术家占筮推演及风角堪舆诸家，均不能废纳音以为言，而莫知其所由来。因备六爻所属，并列《内经》及扬子云、抱朴子诸家之图于后，庶阅者可悉其始末矣。</p><p>纳音始于黄帝，今《内经》所载最详。京氏六十律与甲子分配，自是古法。盖以一律纳五音，十二律纳六十音。《内经》五音，始于金，传火传木传水传土。阳律阴吕，隔八相生。葛稚川曰：“一言得之者，宫与土 【所属者即一言而得】 。三言得之者，徵与火 【如戊去庚三位，故曰三言。下仿此】 。五言得之者，羽与水。七言得之者，商与金。九言得之者，角与木。故子午九，丑未八，寅申七，卯酉六，辰戌五，巳亥四也。”扬子云《太玄》以火土木金水为序，与《内经》不同。甲子乙丑金者，言甲乙子午其数九，乙庚丑未其数八，甲乙子丑积数三十四，以五除之余四，故为金。余仿此数，列右图：</p><p>按：甲己子午九，乙庚辛未八，丙辛寅申七，丁壬卯酉六，戊癸辰戌五，巳亥四 【己亥对宫亥空为虚，己与虚对为孤，己亥者孤虚之数也。】 。黄梨洲先生《象数论》所评议者，颇多未当。其谓甲子乙丑金者，甲九子九，乙八丑八，积三十四，以五除之余四故为金。其数则是，其术则非也。故于丙寅丁卯，丙七寅七丁六卯六积二十六，以五阴之余一故为火，便不成文矣。金四为一当为水，何以为火？而犹曰余准此将无一能合者矣。盖纳音得数之算法，当以大衍为本。以大衍之数五十去一，除去甲己子午之积数，余则以五除之，得一则属水，水生木，其纳音为木。丙寅丁卯之为火，当以积数二十六，除大衍五十去一，余二十三，以五除之余三，属木，木生火，故纳音为火。甲子乙丑之积三十四，以除大衍去一余五，五属土，土生金。非三十四余五余四之谓也。</p><p>纳音纳甲，与天干地支，皆始于黄帝。盖自伏羲画卦，利用宜民，至神农黄帝，文明日进，变化益繁。非单纯八卦之象数所能济用，故益之以阴阳五行。天五地六，迎日推历，布算测地，以尽八卦之用。所谓“穷则变，变则通，通则久”。纳甲取先天，法象乎日月，仰以观于天文也。纳音以先天合后天，取数于阴阳十二消息，以布五行，俯以察于地理也。故京孟之《易》，悉本于此。朱元升《三易备遗》推衍纳音最详，巳亥数伏，一六相合，以为即《归藏》之数，非无见也。</p>',14)])])}const m=p(r,[["render",i]]);export{d as __pageData,m as default};
